const prizes=[{category:'Bebida',name:'Água',stock:4,rotation:1827},{category:'Snack',name:'Barra de cereais',stock:2,rotation:1947},{category:'Prémio Premium',name:'Produto surpresa',stock:1,rotation:2067}];let rotation=0;const wheel=document.querySelector('#wheel'),spin=document.querySelector('#spin'),reset=document.querySelector('#reset'),status=document.querySelector('#status');
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
spin.addEventListener('click',async()=>{const available=prizes.filter(p=>p.stock>0);if(!available.length)return;const prize=available[Math.floor(Math.random()*available.length)];spin.disabled=true;status.textContent='A confirmar pagamento…';await wait(900);status.textContent='A roda está a girar…';rotation+=prize.rotation;wheel.style.transform=`rotate(${rotation}deg)`;await wait(4200);status.textContent='A máquina está a preparar o seu prémio…';await wait(1300);prize.stock--;status.innerHTML=`Parabéns! Ganhou <strong>${prize.name}</strong>.`;spin.hidden=true;reset.hidden=false;});reset.addEventListener('click',()=>{status.textContent='Gira a roda e descobre a tua Mystery Box.';spin.hidden=false;spin.disabled=false;reset.hidden=true;});
